import Foundation

/// The reaction picker's emoji (design/surfaces/chat.reactions.md §3): every fully-qualified emoji of Unicode's RGI set
/// in CLDR order, grouped by Unicode's standard groups, each skin-tone variant attached to the emoji it modifies
/// (touch and hold, as the system emoji keyboard: support.apple.com/102507 "touch and hold an emoji" to change its
/// skin tone). The data is the app's `EmojiCatalog.txt`, generated by `tools/emoji-catalog.mjs` from Unicode's
/// emoji-test.txt; the same file ships in the Android app.
///
/// Format (one line each, tab-separated): `@<group>`; `<emoji>\t<emoji version>\t<CLDR name>`; a leading `+` marks a
/// skin-tone variant of the entry above; `# ` lines are comments.
public struct EmojiCatalog: Sendable, Equatable {
    public struct Emoji: Sendable, Equatable, Hashable {
        public let emoji: String
        /// The Emoji version that added it ("15.1").
        public let version: String
        /// Unicode's CLDR short name ("waving hand: light skin tone"): the search key and the spoken label.
        public let name: String

        public init(emoji: String, version: String, name: String) {
            self.emoji = emoji
            self.version = version
            self.name = name
        }
    }

    public struct Entry: Sendable, Equatable {
        public let base: Emoji
        /// Skin-tone variants in Unicode's order (empty for most emoji).
        public let variants: [Emoji]

        public init(base: Emoji, variants: [Emoji] = []) {
            self.base = base
            self.variants = variants
        }

        /// The base, then its variants: what touch and hold offers.
        public var choices: [Emoji] { [base] + variants }
    }

    public struct Group: Sendable, Equatable {
        /// Unicode's group name ("Smileys & Emotion"); the screens show the copy key in the same position.
        public let name: String
        public let entries: [Entry]

        public init(name: String, entries: [Entry]) {
            self.name = name
            self.entries = entries
        }
    }

    public let groups: [Group]

    public init(groups: [Group]) {
        self.groups = groups
    }

    /// Reads the catalog text. Malformed lines are skipped; a variant before any entry is dropped.
    public init(text: String) {
        var groups: [Group] = []
        var name: String?
        var entries: [Entry] = []
        var base: Emoji?
        var variants: [Emoji] = []

        func closeEntry() {
            if let current = base { entries.append(Entry(base: current, variants: variants)) }
            base = nil
            variants = []
        }
        func closeGroup() {
            closeEntry()
            if let current = name { groups.append(Group(name: current, entries: entries)) }
            entries = []
        }

        for line in text.split(separator: "\n", omittingEmptySubsequences: true) {
            if line.hasPrefix("# ") { continue } // "#️⃣" is an emoji, "# " a comment
            if line.hasPrefix("@") {
                closeGroup()
                name = String(line.dropFirst())
                continue
            }
            let isVariant = line.hasPrefix("+")
            let fields = (isVariant ? line.dropFirst() : line[...]).split(separator: "\t", omittingEmptySubsequences: false)
            guard name != nil, fields.count == 3, !fields[0].isEmpty, !fields[2].isEmpty else { continue }
            let emoji = Emoji(emoji: String(fields[0]), version: String(fields[1]), name: String(fields[2]))
            if isVariant {
                if base != nil { variants.append(emoji) }
            } else {
                closeEntry()
                base = emoji
            }
        }
        closeGroup()
        self.groups = groups
    }

    /// Every emoji (bases and variants) with its name, for spoken labels.
    public var names: [String: String] {
        var out: [String: String] = [:]
        for group in groups {
            for entry in group.entries {
                for item in entry.choices where out[item.emoji] == nil { out[item.emoji] = item.name }
            }
        }
        return out
    }

    /// The catalog without the emoji `isSupported` rejects (newer than the device's emoji font): an entry whose base is
    /// unsupported leaves; unsupported variants leave their entry.
    public func filtered(_ isSupported: (String) -> Bool) -> EmojiCatalog {
        EmojiCatalog(groups: groups.map { group in
            Group(name: group.name, entries: group.entries.compactMap { entry in
                guard isSupported(entry.base.emoji) else { return nil }
                return Entry(base: entry.base, variants: entry.variants.filter { isSupported($0.emoji) })
            })
        })
    }

    /// Search (the picker's C-12 field): base emoji whose name contains `query` (case- and diacritic-insensitive), in
    /// catalog order. An empty query finds nothing.
    public func search(_ query: String) -> [Entry] {
        let needle = query.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !needle.isEmpty else { return [] }
        return groups.flatMap(\.entries).filter {
            $0.base.name.range(of: needle, options: [.caseInsensitive, .diacriticInsensitive]) != nil
        }
    }

    /// The entry whose choices hold `emoji` (a recently used variant finds its base).
    public func entry(containing emoji: String) -> Entry? {
        for group in groups {
            if let found = group.entries.first(where: { $0.choices.contains { $0.emoji == emoji } }) { return found }
        }
        return nil
    }
}
